import sys, json
for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    try:
        obj = json.loads(line)
        if obj.get('type') == 'assistant':
            # Print text content
            for c in obj.get('message', {}).get('content', []):
                if c.get('type') == 'text':
                    print(c['text'][:500])
                    print('---')
        elif obj.get('type') == 'system':
            print(f\"[{obj.get('subtype', '')}] {obj.get('summary', obj.get('description', '')[:200])}\")
    except:
        pass
